# Let’s parse the uploaded gestalt_manifest.md file line by line and generate a full JSON draft.
# This code assumes the format is consistent: each block starts with --- and has fields like date, title, tags, summary.

import json
import re

# Load the uploaded file content
with open("/mnt/data/gestalt_manifest.md", "r") as f:
    lines = f.readlines()

gestalts = []
current = {}

for line in lines:
    line = line.strip()
    if line.startswith("---"):
        if current:
            gestalts.append(current)
            current = {}
    elif line.startswith("##"):
        title = line.replace("##", "").strip()
        current["title"] = title
    elif line.startswith("- Tier:"):
        current["status"] = line.replace("- Tier:", "").strip()
    elif line.startswith("- Tags:"):
        tags_str = line.replace("- Tags:", "").strip()
        tags = [tag.strip() for tag in tags_str.split(",")]
        current["tags"] = tags
    elif line.startswith("- Summary:"):
        summary = line.replace("- Summary:", "").strip()
        current["summary"] = summary
    elif re.match(r"^\d{4}-\d{2}-\d{2}", line):
        date = line.split("T")[0].strip()
        current["date"] = date
    elif line == "":
        continue

# Add the final gestalt if needed
if current:
    gestalts.append(current)

# Add path fields based on title and date
for g in gestalts:
    date_part = g.get("date", "TBD")
    title_part = g.get("title", "Untitled").replace(" ", "_")
    g["path"] = f"gestalts/{date_part}_{title_part}.md"

# Output as JSON
manifest_json = json.dumps(gestalts, indent=2)
manifest_json[:500]  # Preview only the first 500 chars

