import re

# Load the new uploaded gestalt_manifest.md
with open("/mnt/data/gestalt_manifest.md", "r") as f:
    lines = f.readlines()

canonical_entries = []
current = {}

def flush_current():
    """Convert the current entry to canonical format."""
    if not current:
        return
    # Only keep entries that have the canonical pattern
    if "date" in current and "title" in current:
        header = f"### {current['date']} — {current['title']}"
        entry = [header, ""]
        if "thread" in current:
            entry.append(f"- Thread: {current['thread']}")
        if "tags" in current:
            entry.append(f"- Tags: {', '.join(current['tags'])}")
        if "summary" in current:
            entry.append(f"- Summary: {current['summary']}")
        if "status" in current:
            entry.append(f"- Status: {current['status']}")
        entry.append("")
        canonical_entries.append("\n".join(entry))

current = {}
for line in lines:
    stripped = line.strip()
    # Detect canonical header
    match_header = re.match(r"###\s*(\d{4}-\d{2}-\d{2})\s+—\s+(.*)", stripped)
    if match_header:
        flush_current()
        date = match_header.group(1)
        title = match_header.group(2).strip()
        current = {"date": date, "title": title}
    elif stripped.lower().startswith("- thread:"):
        current["thread"] = stripped.split(":", 1)[1].strip()
    elif stripped.lower().startswith("- tags:"):
        tags = stripped.split(":", 1)[1].strip()
        current["tags"] = [tag.strip() for tag in tags.split(",")]
    elif stripped.lower().startswith("- summary:"):
        current["summary"] = stripped.split(":", 1)[1].strip()
    elif stripped.lower().startswith("- status:"):
        current["status"] = stripped.split(":", 1)[1].strip()

# Flush last
flush_current()

# Sort canonical entries by date
def extract_date(entry):
    match = re.match(r"###\s*(\d{4}-\d{2}-\d{2})", entry)
    return match.group(1) if match else ""

canonical_entries.sort(key=extract_date)

# Write cleaned canonical version
with open("/mnt/data/gestalt_manifest_canonical.md", "w") as f:
    f.write("\n".join(canonical_entries))

"/mnt/data/gestalt_manifest_canonical.md"

